PRAGMA foreign_keys=ON;
CREATE TABLE settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE users(id TEXT PRIMARY KEY,name TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('admin','staff')),active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE sessions(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),csrf TEXT NOT NULL,expires_at TEXT NOT NULL);
CREATE TABLE coffees(id TEXT PRIMARY KEY,name TEXT NOT NULL,profile TEXT NOT NULL,brew_days INTEGER NOT NULL CHECK(brew_days>=0),dispatch_days INTEGER CHECK(dispatch_days>=0),retail_days INTEGER CHECK(retail_days>=0),fresh_days INTEGER NOT NULL CHECK(fresh_days>0),yield_bp INTEGER NOT NULL CHECK(yield_bp BETWEEN 1 AND 10000),policy_version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE locations(id TEXT PRIMARY KEY,name TEXT NOT NULL);
CREATE TABLE packages(id TEXT PRIMARY KEY,name TEXT NOT NULL,weight_mg INTEGER NOT NULL CHECK(weight_mg>0));
CREATE TABLE plans(id TEXT PRIMARY KEY,coffee_id TEXT NOT NULL REFERENCES coffees(id),roast_at TEXT NOT NULL,green_mg INTEGER NOT NULL CHECK(green_mg>0),expected_mg INTEGER NOT NULL CHECK(expected_mg>0),status TEXT NOT NULL CHECK(status IN ('planned','completed','cancelled')),explanation TEXT NOT NULL,policy TEXT NOT NULL);
CREATE TABLE batches(id TEXT PRIMARY KEY,code TEXT NOT NULL UNIQUE,coffee_id TEXT REFERENCES coffees(id),external_id TEXT UNIQUE,roasted_at TEXT,green_mg INTEGER NOT NULL DEFAULT 0 CHECK(green_mg>=0),output_mg INTEGER NOT NULL DEFAULT 0 CHECK(output_mg>=0),policy TEXT NOT NULL,notes TEXT NOT NULL DEFAULT '',green_lot TEXT NOT NULL DEFAULT '',held INTEGER NOT NULL DEFAULT 0,hold_reason TEXT NOT NULL DEFAULT '',archived INTEGER NOT NULL DEFAULT 0,history_only INTEGER NOT NULL DEFAULT 0,source_json TEXT,source_updated TEXT,plan_id TEXT UNIQUE REFERENCES plans(id));
CREATE TABLE stocks(id TEXT PRIMARY KEY,batch_id TEXT NOT NULL REFERENCES batches(id),location_id TEXT NOT NULL REFERENCES locations(id),package_id TEXT NOT NULL DEFAULT 'bulk',quantity_mg INTEGER NOT NULL CHECK(quantity_mg>=0),version INTEGER NOT NULL DEFAULT 0,UNIQUE(batch_id,location_id,package_id));
CREATE TABLE movements(id TEXT PRIMARY KEY,kind TEXT NOT NULL,at TEXT NOT NULL,actor TEXT NOT NULL,reason TEXT NOT NULL DEFAULT '',request_id TEXT NOT NULL UNIQUE,payload_hash TEXT NOT NULL,reversal_of TEXT UNIQUE REFERENCES movements(id));
CREATE TABLE entries(id INTEGER PRIMARY KEY AUTOINCREMENT,movement_id TEXT NOT NULL REFERENCES movements(id),stock_id TEXT NOT NULL REFERENCES stocks(id),delta_mg INTEGER NOT NULL);
CREATE TABLE orders(id TEXT PRIMARY KEY,number TEXT NOT NULL,payment TEXT NOT NULL,cancelled INTEGER NOT NULL DEFAULT 0,fulfillment TEXT NOT NULL DEFAULT '',updated_at TEXT NOT NULL,due_at TEXT,notes TEXT NOT NULL DEFAULT '',delivery TEXT NOT NULL DEFAULT '',source TEXT NOT NULL DEFAULT 'manual');
CREATE TABLE variants(id TEXT PRIMARY KEY,sku TEXT NOT NULL DEFAULT '',coffee_id TEXT REFERENCES coffees(id),package_id TEXT REFERENCES packages(id),kind TEXT NOT NULL CHECK(kind IN ('coffee','noncoffee','unresolved')),grind TEXT NOT NULL DEFAULT '');
CREATE TABLE lines(id TEXT PRIMARY KEY,order_id TEXT NOT NULL REFERENCES orders(id),variant_id TEXT NOT NULL,title TEXT NOT NULL,quantity INTEGER NOT NULL CHECK(quantity>=0),unfulfilled INTEGER NOT NULL CHECK(unfulfilled>=0));
CREATE TABLE demands(id TEXT PRIMARY KEY,coffee_id TEXT NOT NULL REFERENCES coffees(id),channel TEXT NOT NULL CHECK(channel IN ('brew','retail')),due_at TEXT NOT NULL,quantity_mg INTEGER NOT NULL CHECK(quantity_mg>=0),note TEXT NOT NULL DEFAULT '');
CREATE TABLE reservations(id TEXT PRIMARY KEY,stock_id TEXT NOT NULL REFERENCES stocks(id),line_id TEXT REFERENCES lines(id),demand_id TEXT REFERENCES demands(id),quantity_mg INTEGER NOT NULL CHECK(quantity_mg>0),use TEXT NOT NULL CHECK(use IN ('brew','dispatch','retail')),due_at TEXT NOT NULL,created_at TEXT NOT NULL,CHECK((line_id IS NULL)!=(demand_id IS NULL)));
CREATE TABLE fulfillment_events(id TEXT PRIMARY KEY,order_id TEXT NOT NULL REFERENCES orders(id),at TEXT NOT NULL,payload TEXT NOT NULL,recorded INTEGER NOT NULL DEFAULT 0);
CREATE TABLE issues(id TEXT PRIMARY KEY,source TEXT NOT NULL,external_id TEXT NOT NULL,kind TEXT NOT NULL,detail TEXT NOT NULL,created_at TEXT NOT NULL,resolved INTEGER NOT NULL DEFAULT 0,UNIQUE(source,external_id,kind));
CREATE TABLE imports(source TEXT NOT NULL,external_id TEXT NOT NULL,payload TEXT NOT NULL,updated_at TEXT NOT NULL,PRIMARY KEY(source,external_id));
CREATE TABLE bean_mappings(external_id TEXT PRIMARY KEY,coffee_id TEXT NOT NULL REFERENCES coffees(id));
CREATE TABLE sync_runs(id TEXT PRIMARY KEY,source TEXT NOT NULL,started_at TEXT NOT NULL,finished_at TEXT,status TEXT NOT NULL,message TEXT NOT NULL);
CREATE TABLE audit(id INTEGER PRIMARY KEY AUTOINCREMENT,at TEXT NOT NULL,actor TEXT NOT NULL,action TEXT NOT NULL,detail TEXT NOT NULL);
CREATE INDEX entries_stock ON entries(stock_id);
CREATE INDEX reservations_stock ON reservations(stock_id);
CREATE INDEX reservations_line ON reservations(line_id);
CREATE INDEX batches_roasted ON batches(roasted_at);
CREATE INDEX lines_order ON lines(order_id);
CREATE TRIGGER entries_no_update BEFORE UPDATE ON entries BEGIN SELECT RAISE(ABORT,'Ledger entries are immutable'); END;
CREATE TRIGGER entries_no_delete BEFORE DELETE ON entries BEGIN SELECT RAISE(ABORT,'Ledger entries are immutable'); END;
CREATE TRIGGER movements_no_update BEFORE UPDATE ON movements BEGIN SELECT RAISE(ABORT,'Movements are immutable'); END;
CREATE TRIGGER movements_no_delete BEFORE DELETE ON movements BEGIN SELECT RAISE(ABORT,'Movements are immutable'); END;
